def compress(nums: list[int]) -> str:
    """See SPEC.md."""
    uniq = sorted(set(nums))
    parts: list[str] = []
    i = 0
    while i < len(uniq):
        j = i
        while j + 1 < len(uniq) and uniq[j + 1] == uniq[j] + 1:
            j += 1
        if j - i >= 2:
            a, b = uniq[i], uniq[j]
            if a < 0:
                a = f"({a})"
            if b < 0:
                b = f"({b})"
            parts.append(f"{a}-{b}")
        else:
            parts.append(str(uniq[i]))
        i = j + 1
    return ",".join(parts)

